          <a href="#">Service 2</a>
          <a href="#">Service 3</a>
        </div>
      </li>
      <li><a href="#contact">Contact</a></li>
    </ul>
    <div class="burger">
      <div class="line1"></div>
      <div class="line2"></div>
      <div class="line3"></div>
    </div>
  </nav>

  <div id="home" class="section">Home Section</div>
  <div id="about" class="section">About Section</div>
  <div id="products" class="section">Products Section</div>
