import { Component } from '@angular/core';

@Component({
  selector: 'app-user',
  templateUrl: './user.component.html',
  styleUrls: ['./user.component.css']
})
export class UserComponent {
  originalUser: any;
  user: any;
  isEditingName: boolean = false;
  isEditingAge: boolean = false;
  isEditingEmail: boolean = false;
  errorMessage: string = '';

  ngOnInit() {
    this.originalUser = { ...user };
    this.user = { ...user };
  }

  toggleEditingName() {
    this.isEditingName = !this.isEditingName;
  }

  toggleEditingAge() {
    this.isEditingAge = !this.isEditingAge;
  }

  toggleEditingEmail() {
    this.isEditingEmail = !this.isEditingEmail;
  }

  updateName() {
    if (this.user.name.trim() === '') {
      this.errorMessage = 'Name is required.';
      return;
    }

    this.errorMessage = '';
    this.isEditingName = false;
  }

  updateAge() {
    if (isNaN(this.user.age) || this.user.age < 0) {
      this.errorMessage = 'Age must be a positive number.';
      return;
    }

    this.errorMessage = '';
    this.isEditingAge = false;
  }

  updateEmail() {
    if (!this.isValidEmail(this.user.email)) {
      this.errorMessage = 'Email is not valid.';
      return;
    }

    this.errorMessage = '';
    this.isEditingEmail = false;
  }

  reset() {
    this.user = { ...this.originalUser };
    this.errorMessage = '';
    this.isEditingName = false;
    this.isEditingAge = false;
    this.isEditingEmail = false;
  }

  isValidEmail(email: string) {
    // You can use a regular expression or any email validation library
    // to validate the email format.
    // For simplicity, let's assume any non-empty string is a valid email.
    return email.trim() !== '';
  }
}

