public class HyperbolicPoint {
    private double t; // time-like coordinate
    private double r; // radial-like coordinate
    private double theta; // angular-like coordinate
    private double phi; // hyperbolic-like coordinate

    public HyperbolicPoint(double t, double r, double theta, double phi) {
        this.t = t;
        this.r = r;
        this.theta = theta;
        this.phi = phi;
    }

