        return phi;
    }

    public void setPhi(double phi) {
        this.phi = phi;
    }

    // Method to calculate distance between two points in 4D space using hyperbolic coordinates
    public static double distance(HyperbolicPoint p1, HyperbolicPoint p2) {
        double dt = p2.getT() - p1.getT();
        double dr = p2.getR() - p1.getR();
        double dTheta = p2.getTheta() - p1.getTheta();
        double dPhi = p2.getPhi() - p1.getPhi();

        // Distance calculation using hyperbolic coordinates formula
        double distanceSquared = Math.pow(dt, 2) - Math.pow(dr, 2) - Math.pow(dTheta, 2) - Math.pow(dPhi, 2);
        double distance = Math.sqrt(Math.abs(distanceSquared)); // Taking absolute value to handle imaginary distances

