      const { course, grade } = this.grades[i];
      const credits = course.credits; // Assuming each course has a 'credits' property
      weightedSum += grade * credits;
      totalCredits += credits;
    }

    return weightedSum / totalCredits;
  }

  calculateHighestGrade() {
    if (this.numCourses === 0) return 0;

    let highestGrade = this.grades[0].grade;

    for (let i = 1; i < this.grades.length; i++) {
      if (this.grades[i].grade > highestGrade) {
        highestGrade = this.grades[i].grade;
      }
