      const credits = course.credits; // Assuming each course has a 'credits' property
      totalGradePoints += gradePoints[grade] * credits;
      totalCredits += credits;
    }

    return totalGradePoints / totalCredits;
  }

  getCoursesAboveGradeThreshold(gradeThreshold) {
